const D = { scale:1, n:60, energy:.55, cohesion:1, align:1, separate:1, glow:.7, density:.6, speed:1, hue:190, x:.5, y:.5, style:'biolum', act:'school', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU2 = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(6, Math.min(120, Math.round(P.n)));
const ho = P.hue - 190;

const STY = {
  biolum:     { water:[[204,72,30],[210,88,15],[222,92,5]],  fH:180, fS:85, fB:100, mode:'glow', add:true },
  xray:       { water:[[208,58,24],[214,72,13],[220,84,5]],  fH:192, fS:55, fB:96,  mode:'xray', add:true },
  silhouette: { water:[[200,50,42],[204,58,26],[210,70,11]], fH:210, fS:38, fB:9,   mode:'sil',  add:false },
  sketch:     { water:[[205,20,30],[208,26,20],[212,34,10]], fH:205, fS:8,  fB:94,  mode:'sketch', add:false },
  thermal:    { water:[[250,62,12],[256,56,8],[262,52,4]],   fH:0,   fS:0,  fB:0,   mode:'thermal', add:true } };
const st = STY[P.style] || STY.biolum;

// ---- cached deep-water gradient buffer ----
const wKey = width + 'x' + height + P.style + P.seed + Math.round(P.hue);
if (!S.bg || S.bgKey !== wKey) {
  if (!S.bg) S.bg = createGraphics(width, height);
  else S.bg.resizeCanvas(width, height);
  const g = S.bg;
  g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke();
  const c = st.water;
  for (let yy = 0; yy < height; yy++) {
    const t = yy / height;
    let a, b2, f;
    if (t < 0.5) { a = c[0]; b2 = c[1]; f = t / 0.5; }
    else { a = c[1]; b2 = c[2]; f = (t - 0.5) / 0.5; }
    const hh = hw(a[0] + (b2[0] - a[0]) * f + ho);
    const ss = a[1] + (b2[1] - a[1]) * f;
    const bb = a[2] + (b2[2] - a[2]) * f;
    g.fill(hh, ss, bb);
    g.rect(0, yy, width, 1);
  }
  // seeded marine speckle in mid-water
  const nsp = 34 + (P.seed % 26);
  for (let i = 0; i < nsp; i++) {
    g.fill(hw(st.fH + ho + 10), 20, st.add ? 70 : 60, 12 * fr(i * 4 + 3));
    g.rect(fr(i * 4 + 1) * width, fr(i * 4 + 2) * height, 1.3, 1.3);
  }
  S.bgKey = wKey;
}
image(S.bg, 0, 0);

// ---- god rays (surface light shafts) — sway on K.t, never re-phase ----
push();
blendMode(ADD);
noStroke();
const rayN = 4;
const rayA = (0.5 + 0.8 * P.density);
for (let r = 0; r < rayN; r++) {
  const base = (r + 0.5) / rayN;
  const sway = 0.08 * Math.sin(K.t * 0.13 + r * 1.7);
  const tx = width * (base + sway);
  const w1 = u * 0.05, w2 = u * 0.26;
  fill(hw(st.fH + ho + 24), 24, st.add ? 92 : 80, 4.2 * rayA);
  beginShape();
  vertex(tx - w1, 0);
  vertex(tx + w1, 0);
  vertex(tx + w2, height);
  vertex(tx - w2, height);
  endShape(CLOSE);
}
blendMode(BLEND);
pop();

// ---- marine snow (continuous downward drift via K.t) ----
push();
blendMode(ADD);
noStroke();
const snowN = Math.floor(40 + 90 * P.density);
const fall = u * 0.035;
for (let i = 0; i < snowN; i++) {
  const sx = fr(i * 3 + 11) * width + 8 * Math.sin(K.t * 0.4 + i);
  const sy = (fr(i * 3 + 13) * height + K.t * fall * (0.4 + fr(i * 3 + 17))) % height;
  const ss = u * 0.004 * (0.6 + fr(i * 3 + 19));
  fill(hw(st.fH + ho + 30), 14, st.add ? 88 : 74, 22);
  ellipse(sx, (sy + height) % height, ss, ss);
}
blendMode(BLEND);
pop();

// ---- flock init / rebuild ----
if (!S.f || S.fn !== N || S.fseed !== P.seed) {
  S.f = [];
  for (let i = 0; i < N; i++) {
    S.f.push({
      x: fr(i * 2 + 1) * width,
      y: fr(i * 2 + 2) * height,
      vx: (fr(i * 3 + 5) - 0.5) * 2,
      vy: (fr(i * 3 + 7) - 0.5) * 2,
      ph: fr(i + 9) * TAU2 });
  }
  S.fn = N; S.fseed = P.seed;
}

const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = {
  school:  [[1,1,1,0],[1.2,1.1,.9,0],[1.4,1,.8,1],[1,1,1,0],[1.3,1.1,.9,0],[1.1,1,1,1],[1.4,1.1,.8,0],[1,1,1,0]],
  hunt:    [[1.3,1,.9,1],[1.5,1.1,.8,1],[1.2,1,1,0],[1.5,1.1,.8,1],[1.3,1,.9,1],[1.6,1,.7,1],[1.2,1.1,1,0],[1.4,1,.8,1]],
  drift:   [[.7,.9,1.3,0],[.6,.8,1.4,0],[.8,1,1.2,1],[.6,.9,1.3,0],[.7,.8,1.4,0],[.5,.9,1.5,0],[.8,1,1.2,1],[.6,.8,1.3,0]] };
const w = (ACT[P.act] || ACT.school)[sec];
const inten = 0.5 + 0.6 * K.intensity;
const cohW = P.cohesion * w[0] * (1 + A.bass * 1.5);
const aliW = P.align * w[1];
const sepW = P.separate * w[2];
const predFlag = w[3] > 0.5;

// ---- predator (dart event per predator section) ----
if (!S.pred) S.pred = { x:-9999, y:0, vx:0, vy:0, on:false };
const pd = S.pred;
if (predFlag && !S.predPrev) {
  const side = fr(sec * 13 + 7) > 0.5 ? 1 : -1;
  pd.x = side > 0 ? -u * 0.12 : width + u * 0.12;
  pd.y = height * (0.2 + 0.6 * fr(sec * 13 + 9));
  const psp = (2.6 + 2.2 * P.energy) * P.speed;
  pd.vx = side > 0 ? psp : -psp;
  pd.vy = (fr(sec * 13 + 11) - 0.5) * psp * 0.5;
  pd.on = true;
}
S.predPrev = predFlag;
if (pd.on) {
  pd.vy += Math.sin(K.t * 1.3) * 0.09;
  pd.x += pd.vx; pd.y += pd.vy;
  if (pd.x < -u * 0.25 || pd.x > width + u * 0.25) pd.on = false;
}

const cxT = width * (P.x + 0.2 * Math.sin(K.t * 0.05 + 1));
const cyT = height * (P.y + 0.14 * Math.sin(K.t * 0.037));
const spd = (1.1 + 2.0 * P.energy) * inten * P.speed;
const scat = A.mid * 1.0 + K.pulse * 0.18;
const bi = Math.floor(K.beat);
const r2 = (u * 0.12) * (u * 0.12);
const sep2 = (u * 0.04) * (u * 0.04);
const hb = width * 0.5, vb = height * 0.5;
const predR = u * 0.2, predR2 = predR * predR;
const f = S.f;

for (let i = 0; i < N; i++) {
  const p = f[i];
  let ax = 0, ay = 0, cx = 0, cy = 0, sx = 0, sy = 0, cnt = 0;
  for (let j = 0; j < N; j++) {
    if (j === i) continue;
    const o = f[j];
    let dx = o.x - p.x, dy = o.y - p.y;
    if (dx > hb) dx -= width; else if (dx < -hb) dx += width;
    if (dy > vb) dy -= height; else if (dy < -vb) dy += height;
    const d2 = dx * dx + dy * dy;
    if (d2 < r2) {
      ax += o.vx; ay += o.vy; cx += dx; cy += dy; cnt++;
      if (d2 < sep2 && d2 > 0.01) { sx -= dx / d2 * 45; sy -= dy / d2 * 45; }
    }
  }
  if (cnt > 0) {
    ax /= cnt; ay /= cnt; cx /= cnt; cy /= cnt;
    p.vx += ax * 0.04 * aliW + cx * 0.0012 * cohW + sx * 0.02 * sepW;
    p.vy += ay * 0.04 * aliW + cy * 0.0012 * cohW + sy * 0.02 * sepW;
  }
  let tx = cxT - p.x, ty = cyT - p.y;
  const tl = Math.hypot(tx, ty) + 0.001; tx /= tl; ty /= tl;
  p.vx += tx * 0.015; p.vy += ty * 0.015;
  // predator flee = dart
  if (pd.on) {
    const ex = p.x - pd.x, ey = p.y - pd.y;
    const e2 = ex * ex + ey * ey;
    if (e2 < predR2 && e2 > 1) {
      const el = Math.sqrt(e2);
      const force = (1 - el / predR) * spd * 2.4;
      p.vx += ex / el * force; p.vy += ey / el * force;
    }
  }
  p.vx += (fr(i + bi) - 0.5) * scat;
  p.vy += (fr(i * 7 + bi) - 0.5) * scat;
  let sp = Math.hypot(p.vx, p.vy);
  if (sp > spd) { p.vx = p.vx / sp * spd; p.vy = p.vy / sp * spd; sp = spd; }
  const flo = spd * 0.4;
  if (sp < flo) { const bb = flo / (sp + 0.001); p.vx *= bb; p.vy *= bb; }
  p.x += p.vx; p.y += p.vy;
  if (p.x < 0) p.x += width; else if (p.x >= width) p.x -= width;
  if (p.y < 0) p.y += height; else if (p.y >= height) p.y -= height;
}

// ---- render fish ----
noStroke();
if (st.add) blendMode(ADD);
const L = u * 0.03 * P.scale;
const gl = P.glow;
const bh = hw(st.fH + ho);
const spark = 0.6 + 0.6 * A.treble;
for (let i = 0; i < N; i++) {
  const p = f[i];
  const ang = Math.atan2(p.vy, p.vx);
  const wag = Math.sin(K.beat * TAU2 * 1.4 + p.ph) * 0.5;
  push();
  translate(p.x, p.y);
  rotate(ang);
  if (st.mode === 'glow') {
    // dim body + bioluminescent lateral spots
    fill(bh, st.fS, 34, 44);
    beginShape();
    vertex(L * 1.15, 0);
    vertex(L * 0.1, L * 0.42);
    vertex(-L * 0.7, L * 0.2 + wag * L * 0.5);
    vertex(-L * 1.1, wag * L * 0.9);
    vertex(-L * 0.7, -L * 0.2 + wag * L * 0.5);
    vertex(L * 0.1, -L * 0.42);
    endShape(CLOSE);
    fill(bh, st.fS - 10, st.fB, 66 * gl * spark);
    for (let d = 0; d < 4; d++) {
      const dx = L * (0.7 - d * 0.42);
      ellipse(dx, 0, L * 0.16, L * 0.16);
    }
    fill(hw(bh + 30), 60, 100, 80 * gl);
    ellipse(L * 0.85, 0, L * 0.16, L * 0.16);
  } else if (st.mode === 'xray') {
    // anatomical: spine + ribs + translucent envelope
    stroke(bh, st.fS, st.fB, 20);
    strokeWeight(1);
    noFill();
    beginShape();
    vertex(L * 1.1, 0);
    vertex(-L * 0.7, L * 0.34);
    vertex(-L * 1.1, wag * L);
    vertex(-L * 0.7, -L * 0.34);
    endShape(CLOSE);
    stroke(bh, st.fS, st.fB, 70);
    line(L * 0.9, 0, -L * 0.9, wag * L * 0.6);
    strokeWeight(0.8);
    for (let ribi = 0; ribi < 5; ribi++) {
      const rx = L * (0.7 - ribi * 0.34);
      const rt = 1 - ribi / 6;
      line(rx, 0, rx - L * 0.12, L * 0.3 * rt);
      line(rx, 0, rx - L * 0.12, -L * 0.3 * rt);
    }
    noStroke();
    fill(hw(bh + 20), 70, 100, 60 * gl);
    ellipse(L * 0.82, 0, L * 0.18, L * 0.18);
  } else if (st.mode === 'sil') {
    fill(bh, st.fS, st.fB, 96);
    beginShape();
    vertex(L * 1.15, 0);
    vertex(L * 0.1, L * 0.44);
    vertex(-L * 0.7, L * 0.22);
    vertex(-L * 1.15, wag * L * 1.0 + L * 0.5);
    vertex(-L * 1.15, wag * L * 1.0 - L * 0.5);
    vertex(-L * 0.7, -L * 0.22);
    vertex(L * 0.1, -L * 0.44);
    endShape(CLOSE);
  } else if (st.mode === 'sketch') {
    noFill();
    stroke(bh, st.fS, st.fB, 90);
    strokeWeight(1.2);
    const wob = (fr(i) - 0.5) * L * 0.1;
    beginShape();
    vertex(L * 1.12 + wob, 0);
    vertex(L * 0.1, L * 0.42);
    vertex(-L * 0.7, L * 0.2);
    vertex(-L * 1.05, wag * L * 0.9);
    vertex(-L * 0.7, -L * 0.2);
    vertex(L * 0.1, -L * 0.42);
    endShape(CLOSE);
    strokeWeight(0.6);
    for (let hi = 0; hi < 3; hi++) {
      const hx = L * (0.4 - hi * 0.3);
      line(hx, -L * 0.2, hx - L * 0.15, L * 0.2);
    }
    line(L * 0.55, -L * 0.05, L * 0.55, L * 0.05);
  } else { // thermal — heat ramp by speed
    const sp = Math.hypot(p.vx, p.vy) / (spd + 0.001);
    let hh, ss2, bb2;
    if (sp < 0.5) { hh = 240 - sp * 2 * 60; ss2 = 90; bb2 = 40 + sp * 2 * 40; }
    else { const t2 = (sp - 0.5) * 2; hh = 60 - t2 * 60 + 60; ss2 = 90 - t2 * 60; bb2 = 80 + t2 * 20; }
    fill(hw(hh + ho * 0.2), Math.max(0, ss2), Math.min(100, bb2), 82 * gl);
    beginShape();
    vertex(L * 1.15, 0);
    vertex(L * 0.1, L * 0.42);
    vertex(-L * 0.7, L * 0.2);
    vertex(-L * 1.1, wag * L * 0.9);
    vertex(-L * 0.7, -L * 0.2);
    vertex(L * 0.1, -L * 0.42);
    endShape(CLOSE);
  }
  pop();
}

// predator render (dark menacing mass with eye)
if (pd.on) {
  const pang = Math.atan2(pd.vy, pd.vx);
  const PL = L * 2.6;
  push();
  translate(pd.x, pd.y);
  rotate(pang);
  if (st.add) blendMode(BLEND);
  noStroke();
  fill(hw(bh + 200), 40, st.mode === 'sil' ? 4 : 12, 88);
  beginShape();
  vertex(PL * 1.1, 0);
  vertex(0, PL * 0.4);
  vertex(-PL * 0.8, PL * 0.16);
  vertex(-PL * 1.05, 0);
  vertex(-PL * 0.8, -PL * 0.16);
  vertex(0, -PL * 0.4);
  endShape(CLOSE);
  fill(hw(bh + 20), 90, 100, 90);
  ellipse(PL * 0.7, -PL * 0.08, PL * 0.1, PL * 0.1);
  pop();
}
if (st.add) blendMode(BLEND);
